import { createHash } from "node:crypto";

/**
 * Every generated file says it is generated, from what, and carries the sha-256 of what
 * Atticus wrote. On the next run a file whose content no longer matches its hash was edited
 * by a person, and is left alone unless `--force`. Files without a header were never
 * Atticus's and are never overwritten. The hash covers the file with the header line removed,
 * so writing the header doesn't change it.
 *
 * Where the header goes depends on the file: after the front matter for Markdown with front
 * matter (assistants need `---` on the first line), after the shebang for shell scripts, and
 * as a marked section for files a person shares with Atticus (CLAUDE.md,
 * .github/copilot-instructions.md).
 */

export const sha256 = (s: string) => createHash("sha256").update(s, "utf8").digest("hex");

export type CommentStyle = "html" | "hash";

const TAG = "atticus-sha256";
const HEADER_RE = new RegExp(
  `^(?:<!--|#) Generated by Atticus from (.+?)\\. .*${TAG}: ([0-9a-f]{64})(?: -->)?$`,
);
export const BEGIN_RE = new RegExp(
  `^<!-- atticus:begin generated from (.+?); ${TAG}: ([0-9a-f]{64}) -->$`,
);
export const END = "<!-- atticus:end -->";

export function headerLine(style: CommentStyle, source: string, hash: string): string {
  const text = `Generated by Atticus from ${source}. Edit the source instead: Atticus regenerates this file and keeps hand edits only until --force. ${TAG}: ${hash}`;
  return style === "html" ? `<!-- ${text} -->` : `# ${text}`;
}

/** Where the header line goes: after front matter or a shebang, else first. */
function insertAt(lines: string[]): number {
  if (lines[0] === "---") {
    const close = lines.indexOf("---", 1);
    return close > 0 ? close + 1 : 0;
  }
  if (lines[0]?.startsWith("#!")) return 1;
  return 0;
}

/** Add the header to rendered content (which must end with a newline). */
export function withHeader(content: string, style: CommentStyle, source: string): string {
  const lines = content.split("\n");
  const at = insertAt(lines);
  lines.splice(at, 0, headerLine(style, source, sha256(content)));
  return lines.join("\n");
}

export interface ParsedHeader {
  source: string;
  hash: string;
  /** The file with the header line removed: what the hash is checked against. */
  body: string;
}

/** Find the header in a whole generated file; undefined when the file has none. */
export function parseHeader(text: string): ParsedHeader | undefined {
  const lines = text.replace(/\r\n/g, "\n").split("\n");
  const at = insertAt(lines);
  for (const i of [at, 0, 1]) {
    const m = HEADER_RE.exec(lines[i] ?? "");
    if (!m) continue;
    const body = [...lines.slice(0, i), ...lines.slice(i + 1)].join("\n");
    return { source: m[1]!, hash: m[2]!, body };
  }
  return undefined;
}

export interface Section {
  /** Line index (0-based) of the begin marker and of the end marker. */
  start: number;
  end: number;
  source: string;
  hash: string;
  /** What sits between the markers. */
  inner: string;
}

/** A marked Atticus section inside a file a person also writes. */
export function findSection(text: string): Section | undefined {
  const lines = text.replace(/\r\n/g, "\n").split("\n");
  const b = lines.findIndex((l) => BEGIN_RE.test(l));
  if (b < 0) return undefined;
  const e = lines.indexOf(END, b + 1);
  if (e < 0) return undefined;
  const m = BEGIN_RE.exec(lines[b]!)!;
  return {
    start: b,
    end: e,
    source: m[1]!,
    hash: m[2]!,
    inner: lines.slice(b + 1, e).join("\n"),
  };
}

export function renderSection(inner: string, source: string): string {
  const body = inner.replace(/\n+$/, "");
  return `<!-- atticus:begin generated from ${source}; ${TAG}: ${sha256(body)} -->\n${body}\n${END}`;
}
